"""Golden math/serialization captured from pinned upstream, never regenerated by tests."""

import json
from pathlib import Path

import pytest
from migration_cases import jsonable
from training_cases import cases

from search_r1.training.data import assemble_training_data, compute_advantages
from search_r1.training.metrics import compute_kl_sample_train, compute_trajectory_metrics
from search_r1.training.records import serialize_rollout_summaries

REFERENCE = json.loads((Path(__file__).parent / "fixtures/training_reference.json").read_text())


@pytest.mark.parametrize("case", list(cases()))
def test_fixed_upstream_math(case):
    groups = cases()[case]
    advantages = compute_advantages(groups)
    data, metadata = assemble_training_data(groups, advantages)
    tags = [["nq"] if i % 2 == 0 else ["hotpot"] for i in range(len(groups))]
    actual = {
        "advantages": [a.tolist() for a in advantages],
        "data": json.loads(json.dumps(jsonable(data), default=lambda value: value.tolist())),
        "metadata": metadata,
        "metrics": compute_trajectory_metrics(groups, tags),
        "records": serialize_rollout_summaries(
            split="train",
            iteration=7,
            trajectory_groups_P=groups,
            taglist_P=tags,
            sampling_client_steps_P=[7] * len(groups),
        ),
    }
    if data:
        actual["kl"] = compute_kl_sample_train(
            data, [d.loss_fn_inputs["logprobs"].to_torch() + 0.125 for d in data]
        )
    assert actual == REFERENCE["cases"][case]


@pytest.mark.parametrize("substeps", [1, 3])
def test_fixed_upstream_sdk_submission_contract(tmp_path, substeps):
    import asyncio
    from types import SimpleNamespace

    import chz
    from test_training_loop import Ready, config

    from search_r1.training.update import update_groups

    events = []

    class Client:
        def forward_backward(self, data, loss_fn, loss_fn_config):
            events.append(["forward", len(data), loss_fn, loss_fn_config])
            assert all("mask" not in d.loss_fn_inputs for d in data)
            return Ready(
                SimpleNamespace(
                    loss_fn_outputs=[{"logprobs": d.loss_fn_inputs["logprobs"]} for d in data]
                )
            )

        def optim_step(self, params):
            events.append(["adam", jsonable(params)])
            return Ready(
                SimpleNamespace(metrics={"last_optimizer": sum(e[0] == "adam" for e in events)})
            )

        def save_weights_and_get_sampling_client(self, **kwargs):
            events.append(["publish", kwargs])
            return Ready("snapshot")

    cfg = chz.replace(
        config(tmp_path), num_substeps=substeps, loss_fn_config={"clip_low_threshold": 0.2}
    )
    result = asyncio.run(update_groups(Client(), cfg, cases()["centered_partial_rewards"]))
    reference = REFERENCE["updates"][str(substeps)]
    assert (
        json.loads(json.dumps(events, default=lambda value: value.tolist())) == reference["events"]
    )
    assert result.metrics["last_optimizer"] == reference["metrics"]["last_optimizer"]
    assert [d.loss_fn_inputs["logprobs"].tolist() for d in result.data] == reference["logprobs"]
    assert result.sampler == "snapshot"
